  void DecorateSlider(Slider slider,bool percent){if(slider.Parent is not StackPanel p)return;int i=p.Children.IndexOf(slider);if(i<=0||p.Children[i-1] is not TextBlock label)return;string title=label.Text;p.Children.RemoveAt(i-1);var row=new DockPanel{Margin=label.Margin};var value=Dynamic(new TextBlock{FontWeight=FontWeights.SemiBold},TextBlock.ForegroundProperty,"Accent");var pill=Dynamic(new Border{CornerRadius=new CornerRadius(11),Padding=new Thickness(9,3,9,3),Child=value},Border.BackgroundProperty,"AccentSoft");DockPanel.SetDock(pill,Dock.Right);row.Children.Add(pill);row.Children.Add(Dynamic(new TextBlock{Text=title,FontWeight=FontWeights.SemiBold,VerticalAlignment=VerticalAlignment.Center},TextBlock.ForegroundProperty,"Text"));p.Children.Insert(i-1,row);Action update=()=>{int v=(int)Math.Round(slider.Value);value.Text=(v>0?"+":"")+v+(percent?"%":"");};slider.ValueChanged+=(_,__)=>update();update();}
