  void ChooseDriverProbe(){var d=new Microsoft.Win32.OpenFileDialog{Filter="ShadePilot DriverProbe|ShadePilot.DriverProbe.exe|可执行文件|*.exe"};if(d.ShowDialog(this)!=true)return;driverProbePath=d.FileName;driverStatus.Text="已选择 Probe："+IOPath.GetFileName(driverProbePath);}
  void ChooseDriverControl(){var d=new Microsoft.Win32.OpenFileDialog{Filter="ShadePilot DriverControl|ShadePilot.DriverControl.exe|可执行文件|*.exe"};if(d.ShowDialog(this)!=true)return;driverControlPath=d.FileName;driverStatus.Text="已选择控制器："+IOPath.GetFileName(driverControlPath);}
  void UpdateDriverFilterChoices(){if(driverFilterBox==null)return;var index=driverOutputBox?.SelectedIndex??-1;var output=index>=0&&index<driverOutputs.Count?driverOutputs[index]:null;var types=output?.Filters.Select(f=>f.Type).Distinct().ToArray()??Array.Empty<uint>();driverFilterBox.ItemsSource=types;driverFilterBox.SelectedIndex=types.Length>0?0:-1;if(output!=null&&types.Length>0){var range=output.Filters.First(f=>f.Type==types[0]);driverIntensity.Text=Math.Clamp(output.CurrentIntensity,range.Minimum,range.Maximum).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture);}}
  async Task ReadDriverCapabilities(){if(string.IsNullOrWhiteSpace(driverProbePath)){driverStatus.Text="请先选择 ShadePilot.DriverProbe.exe。";return;}try{var result=await new IntelSharpnessReadProvider(driverProbePath).ReadAsync();if(!result.Succeeded||result.Adapters.Count==0){driverStatus.Text="IGCL 读取失败："+(result.Error??result.Status);return;}var outputs=result.Adapters[0].DisplayOutputs;driverOutputs=outputs;driverOutputBox.ItemsSource=Enumerable.Range(0,outputs.Count).ToArray();driverOutputBox.SelectedIndex=0;UpdateDriverFilterChoices();var supported=outputs.FirstOrDefault(x=>x.SharpnessCapsResult=="0x0");driverStatus.Text=supported==null?"已读取，但没有输出报告 Sharpness 能力。":$"已读取 {result.Adapters[0].Name}；可用输出 {supported.Index}，范围 {supported.Filters.FirstOrDefault()?.Minimum}–{supported.Filters.FirstOrDefault()?.Maximum}，当前强度 {supported.CurrentIntensity}；活动标记={(supported.DisplayConfigFlags&1)!=0}，虚拟标记={(supported.EncoderConfigFlags&0x40)!=0}。";}catch(Exception ex){driverStatus.Text="读取失败："+ex.Message;}}
  async Task ApplyDriverSharpness(){if(string.IsNullOrWhiteSpace(driverControlPath)){driverStatus.Text="请先选择 ShadePilot.DriverControl.exe。";return;}if(driverFilterBox?.SelectedItem is not uint filterType){driverStatus.Text="请先读取能力并选择受支持的滤镜类型。";return;}if(!float.TryParse(driverIntensity.Text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var intensity)){driverStatus.Text="强度必须是数字。";return;}var backup=IOPath.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ShadePilot","driver-backups","sharpness-backup.txt");Directory.CreateDirectory(IOPath.GetDirectoryName(backup)!);var result=await new IntelSharpnessControlProvider(driverControlPath).SetAsync(new SharpnessWriteRequest(driverOutputBox.SelectedIndex,driverEnabled.IsChecked==true,filterType,intensity,backup));driverStatus.Text=result.Succeeded?$"接口写入并回读成功：滤镜 {filterType}，强度 {result.ReadbackIntensity}；备份已保存。是否可见需用同一画面做 A/B 观察。":"写入失败："+(result.Error??result.SetResult);}
  async Task RestoreDriverSharpness(){if(string.IsNullOrWhiteSpace(driverControlPath)){driverStatus.Text="请先选择 ShadePilot.DriverControl.exe。";return;}var backup=IOPath.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ShadePilot","driver-backups","sharpness-backup.txt");if(!File.Exists(backup)){driverStatus.Text="没有找到最近的 Sharpness 备份。";return;}var result=await new IntelSharpnessControlProvider(driverControlPath).RestoreAsync(backup);driverStatus.Text=result.Succeeded?"已恢复备份并回读确认。":"恢复失败："+(result.Error??result.SetResult);}
#endif
  void ApplyTheme(AppTheme t){SetBrush("Canvas",t.Canvas);SetBrush("Surface",t.Surface);SetBrush("Tint",t.TintSurface);SetBrush("Soft",t.SoftSurface);SetBrush("Accent",t.Accent);SetBrush("AccentSoft",t.AccentSoft);SetBrush("Text",t.Ink);SetBrush("Muted",t.Muted);SetBrush("Border",Mix(t.Surface,t.Muted,.28));Background=(Brush)FindResource("Canvas");Foreground=(Brush)FindResource("Text");}
  void ConfigureToolTips(){SetTip(MonitorBox,"选择需要调节的物理显示器。");SetTip(BrightnessSlider,"调节显示器背光亮度，不等同于提亮暗部。");SetTip(ContrastSlider,"调节显示器硬件对比度；0 表示显示器量程中点。");SetTip(SaturationSlider,"优先使用硬件饱和度，不支持时可选择 Windows 软件色彩；50 为中性。");SetTip(LiveApply,"开启后，拖动硬件滑块会在短暂防抖后自动写入。");SetTip(syncAll,"同步画面风格到所有显示器；硬件亮度和对比度仍只作用于当前显示器。");SetTip(PresetBox,"选择预设；点击应用风格或使用后台快捷键生效。");SetTip(strengthBox,"限制参数可调范围：柔和适合日常，标准兼顾效果，极限开放完整范围。");var tips=new Dictionary<Slider,string>{{Shadows,"提升阴影区域并尽量保留纯黑。"},{Highlights,"压低高亮区域，减少灯光和天空刺眼。"},{Midtones,"调整主体所在的中间亮度。"},{BlackPoint,"正值抬起黑位，负值加深黑色。"},{WhitePoint,"正值增强白场，负值收回最亮区域。"},{ContrastPivot,"围绕中间亮度改变软件曲线对比度。"},{Temperature,"负值偏冷蓝，正值偏暖黄。"},{TintSlider,"负值偏绿，正值偏洋红。"},{Vibrance,"近似增强较柔和颜色，不是逐像素滤镜。"},{Exposure,"整体增减软件曝光，不改变显示器背光。"},{ShadowRange,"改变暗部补偿覆盖范围，不改变强度。"},{HighlightRange,"改变高光压制覆盖范围，不改变强度。"},{Softness,"改变明暗调整边缘的过渡宽度。"}};foreach(var x in tips)SetTip(x.Key,x.Value);}
  static void SetTip(FrameworkElement e,string text){if(e!=null)ToolTipService.SetToolTip(e,new ToolTip{Content=text,MaxWidth=360});}
  void ApplyStrengthMode(int mode){double tonal=mode==0?80:mode==1?150:200,signed=mode==0?40:mode==1?70:100;Shadows.Maximum=Highlights.Maximum=tonal;foreach(var s in new[]{Midtones,BlackPoint,WhitePoint,ContrastPivot,Temperature,TintSlider,Vibrance,Exposure,ShadowRange,HighlightRange,Softness}){s.Minimum=-signed;s.Maximum=signed;}}
  List<string> AnalyzeStyleRisks(){var r=new List<string>();if(Shadows.Value>=55&&BlackPoint.Value>=-3&&ContrastPivot.Value<=10)r.Add("暗部抬升较高但黑位与反差不足，可能灰蒙");if(Shadows.Value>=80&&Midtones.Value>=25)r.Add("暗部和中间调重复提亮");if(Highlights.Value>=70&&WhitePoint.Value<=-18)r.Add("高光与白位重复压缩");if(Exposure.Value>=18&&Highlights.Value>=50)r.Add("曝光提升与高光压制互相抵消");if(Exposure.Value<=-18&&Shadows.Value>=55)r.Add("负曝光与暗部补偿互相抵消");if(Math.Abs(ContrastPivot.Value)>=45&&(Shadows.Value>=45||Highlights.Value>=45))r.Add("中间对比过强，可能覆盖明暗塑形");if(Vibrance.Value>=55&&ContrastPivot.Value>=30)r.Add("自然色彩与高对比叠加，通道可能提前裁切");if(Softness.Value>=45&&(Shadows.Value>=55||Highlights.Value>=55))r.Add("过渡范围过宽，容易降低局部反差");if(Math.Abs(ShadowRange.Value)>=25&&Shadows.Value<10)r.Add("暗部范围已调整，但暗部补偿接近零");if(Math.Abs(HighlightRange.Value)>=25&&Highlights.Value<10)r.Add("高光范围已调整，但高光压制接近零");return r;}
  void UpdateRiskStatus(){if(riskStatus==null)return;var r=AnalyzeStyleRisks();riskStatus.Text=r.Count==0?"曲线状态良好 · 未发现明显灰雾、裁切或参数冲突":"调整建议 · "+string.Join("；",r);riskStatus.SetResourceReference(TextBlock.ForegroundProperty,r.Count==0?"Muted":"Accent");}
  void OptimizeStyle(){var before=AnalyzeStyleRisks();if(before.Count==0){StyleStatus.Text="当前参数没有发现需要自动修正的明显冲突。";return;}loading=true;try{if(Shadows.Value>=55&&BlackPoint.Value>=-3&&ContrastPivot.Value<=10){BlackPoint.Value=Math.Clamp(-Math.Max(6,Math.Min(18,(int)Shadows.Value/9)),BlackPoint.Minimum,BlackPoint.Maximum);ContrastPivot.Value=Math.Max(10,ContrastPivot.Value);}if(Shadows.Value>=80&&Midtones.Value>=25)Midtones.Value=20;if(Highlights.Value>=70&&WhitePoint.Value<=-18)WhitePoint.Value=-12;if(Exposure.Value>=18&&Highlights.Value>=50)Exposure.Value=14;if(Exposure.Value<=-18&&Shadows.Value>=55)Exposure.Value=-12;if(Math.Abs(ContrastPivot.Value)>=45&&(Shadows.Value>=45||Highlights.Value>=45))ContrastPivot.Value=Math.Sign(ContrastPivot.Value)*32;if(Vibrance.Value>=55&&ContrastPivot.Value>=30)Vibrance.Value=45;if(Softness.Value>=45&&(Shadows.Value>=55||Highlights.Value>=55))Softness.Value=30;if(Math.Abs(ShadowRange.Value)>=25&&Shadows.Value<10)ShadowRange.Value=0;if(Math.Abs(HighlightRange.Value)>=25&&Highlights.Value<10)HighlightRange.Value=0;}finally{loading=false;}SyncRuntimeStateFromStyleControls("优化后");UpdateCurve();UpdateRiskStatus();ApplyPreset(Capture("优化后"));StyleStatus.Text=$"已修正 {before.Count} 项参数冲突；整体风格方向保持不变。";}
