  void SourceReady(object s,EventArgs e){hwnd=new WindowInteropHelper(this).Handle;source=HwndSource.FromHwnd(hwnd);source.AddHook(Hook);RegisterHotkeys();}
  IntPtr Hook(IntPtr h,int m,IntPtr w,IntPtr l,ref bool handled){if(m==WM_HOTKEY){handled=true;int id=w.ToInt32();Dispatcher.BeginInvoke(new Action(()=>Hotkey(id)));}return IntPtr.Zero;}
  void Hotkey(int id){if(crosshair?.HandleHotkey(id)==true){hotkeyInfo.Text="后台快捷键刚刚已切换准星（"+DateTime.Now.ToString("HH:mm:ss")+"）";return;}string action="未知";if(hotkeyMap.TryGetValue(id,out var p)){action="应用预设 "+p.Name;ApplyPreset(p);}else if(id==RESTORE){action="恢复原始画面";ResetStyle();}else if(id==CYCLE){action="循环切换";Cycle();}else if(id==ORIGINAL){action="切换原画";ToggleOriginal();}hotkeyInfo.Text="后台快捷键刚刚已响应："+action+"（"+DateTime.Now.ToString("HH:mm:ss")+"）";}
  void RegisterHotkeys(){UnregisterHotkeys();hotkeyStatus.Clear();int id=STYLE_BASE;foreach(var p in styles.Items){if(p.HotkeyKey==0){hotkeyStatus[p.Name]="未设置";continue;}RegisterOne(++id,p.HotkeyModifiers,p.HotkeyKey,p.Name,p);}RegisterOne(RESTORE,styles.RestoreHotkeyModifiers,styles.RestoreHotkeyKey,"恢复原始画面",null);RegisterOne(CYCLE,styles.CycleHotkeyModifiers,styles.CycleHotkeyKey,"循环切换",null);RegisterOne(ORIGINAL,settings.HoldOriginalModifiers,settings.HoldOriginalKey,"切换原画",null);crosshair?.RegisterHotkeys();var fail=hotkeyStatus.Where(x=>x.Value.StartsWith("注册失败")).Select(x=>x.Key+"："+x.Value);hotkeyInfo.Text=fail.Any()?string.Join("；",fail):$"后台快捷键已注册 {registered.Count} 项；窗口隐藏或最小化后仍由 Win32 消息窗口接收。";UpdateTrayStatus();}
  void RegisterOne(int id,uint mod,int key,string name,StylePresetData p){if(key==0){hotkeyStatus[name]="未设置";return;}if(MonitorApi.RegisterHotKey(hwnd,id,mod|0x4000u,(uint)key)){registered.Add(id);if(p!=null)hotkeyMap[id]=p;hotkeyStatus[name]="已注册，可在后台使用";}else hotkeyStatus[name]="注册失败，Win32 错误 "+Marshal.GetLastWin32Error();}
  void UnregisterHotkeys(){if(hwnd!=IntPtr.Zero)foreach(int id in registered)MonitorApi.UnregisterHotKey(hwnd,id);registered.Clear();hotkeyMap.Clear();crosshair?.UnregisterHotkeys();}
  void CaptureOriginalKey(object s,KeyEventArgs e){e.Handled=true;if(e.Key is Key.Back or Key.Delete){settings.HoldOriginalKey=0;settings.HoldOriginalModifiers=0;originalKey.Text="未设置";return;}if(e.Key is Key.LeftCtrl or Key.RightCtrl or Key.LeftAlt or Key.RightAlt or Key.LeftShift or Key.RightShift)return;settings.HoldOriginalModifiers=(Keyboard.Modifiers.HasFlag(ModifierKeys.Alt)?1u:0)|(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)?2u:0)|(Keyboard.Modifiers.HasFlag(ModifierKeys.Shift)?4u:0);settings.HoldOriginalKey=KeyInterop.VirtualKeyFromKey(e.Key);originalKey.Text=HotkeyText(settings.HoldOriginalModifiers,settings.HoldOriginalKey);}

