  void SyncRuntimeStateFromStyleControls(string name=null){if(loading)return;runtimeState=ReadStyleControls(name??runtimeState?.Name??"当前");OnAdvancedStyleChanged();}
  void UpdateRuntimeSaturationFromControl(){var state=(runtimeState??ReadStyleControls("运行态")).DeepClone();state.Saturation=Math.Clamp((int)SaturationSlider.Value,0,100);runtimeState=NormalizeStyleState(state);}
  void ResetStyle(){try{gamma.RestoreAll();softwareSat.Restore();recovery.SetSoftwareColorMayBeActive(false);}catch{}SetControls(new StylePresetData{Name="原始",Saturation=50});activeStyle=null;originalShown=false;StyleStatus.Text="已恢复软件画面；饱和度已回到中性 50，且未自动写入硬件。";}void ToggleOriginal(){if(!originalShown){beforeOriginal=Capture("切换原画前");try{gamma.RestoreAll();softwareSat.Restore();recovery.SetSoftwareColorMayBeActive(false);}catch{}originalShown=true;}else{if(beforeOriginal!=null)ApplyPreset(beforeOriginal.DeepClone());originalShown=false;}}void Cycle(){var names=styles.CyclePresetNames??new List<string>();var available=names.Select(n=>styles.Items.Find(p=>string.Equals(p.Name,n,StringComparison.OrdinalIgnoreCase))).Where(p=>p!=null).ToList();if(available.Count==0){StyleStatus.Text="循环切换没有可用预设，请在快捷键设置中至少选择两个模式。";return;}int active=activeStyle==null?-1:available.FindIndex(p=>string.Equals(p.Name,activeStyle.Name,StringComparison.OrdinalIgnoreCase));if(active>=0)cycleIndex=active;cycleIndex=(cycleIndex+1)%available.Count;ApplyPreset(available[cycleIndex].DeepClone());StyleStatus.Text=$"循环切换：{available[cycleIndex].Name}（{cycleIndex+1}/{available.Count}）";}
  static double ToNeutral50(uint value,uint min,uint max)=>max<=min?50:Math.Clamp((value-min)*100.0/(max-min),0,100);
  static uint FromNeutral50(int value,uint min,uint max)=>max<=min?min:(uint)Math.Round(min+Math.Clamp(value,0,100)/100.0*(max-min));
  static double ToNeutralZero(uint value,uint min,uint max)=>max<=min?0:Math.Clamp((value-min)*100.0/(max-min)-50.0,-50,50);
  static uint FromNeutralZero(int value,uint min,uint max)=>max<=min?min:(uint)Math.Round(min+(Math.Clamp(value,-50,50)+50)/100.0*(max-min));
  void SaveStyle(){string n=Prompt.Ask(this,"保存当前画面风格","输入预设名称");if(string.IsNullOrWhiteSpace(n))return;var p=styles.Items.Find(x=>string.Equals(x.Name,n.Trim(),StringComparison.OrdinalIgnoreCase));if(p==null){p=new StylePresetData{Name=n.Trim()};styles.Items.Add(p);}Copy(Capture(p.Name).DeepClone(),p);styles.Save();recovery.Log("Preset saved: "+p.Name);ReloadPresets(p);RegisterHotkeys();}static void Copy(StylePresetData a,StylePresetData b){b.Shadows=a.Shadows;b.Highlights=a.Highlights;b.Midtones=a.Midtones;b.BlackPoint=a.BlackPoint;b.WhitePoint=a.WhitePoint;b.ContrastPivot=a.ContrastPivot;b.Temperature=a.Temperature;b.Tint=a.Tint;b.Vibrance=a.Vibrance;b.Exposure=a.Exposure;b.ShadowRange=a.ShadowRange;b.HighlightRange=a.HighlightRange;b.TransitionSoftness=a.TransitionSoftness;b.Saturation=a.Saturation;}
  void OpenManager(){new PresetManagerWindow(this,styles,settings,SelectedPreset).ShowDialog();styles.Save();ReloadPresets(null);RegisterHotkeys();}void OpenHotkeys(){new HotkeyWindow(this,styles).ShowDialog();styles.Save();ReloadPresets(SelectedPreset);RegisterHotkeys();}
  void ExportLut(){var state=Capture(activeStyle?.Name??"ShadePilot-current");var d=new Microsoft.Win32.SaveFileDialog{Filter="Adobe Cube 3D LUT (*.cube)|*.cube",FileName=state.Name+".cube",DefaultExt="cube"};if(d.ShowDialog(this)!=true)return;try{CubeLutExporter.Export(d.FileName,33,state.Shadows,state.Highlights,state.Midtones,state.BlackPoint,state.WhitePoint,state.ContrastPivot,state.Temperature,state.Tint,state.Vibrance,state.Saturation,state.Exposure,state.ShadowRange,state.HighlightRange,state.TransitionSoftness);StyleStatus.Text="OBS LUT 已导出。";}catch(Exception ex){StyleStatus.Text="LUT 导出失败："+ex.Message;}}
  void ImportCode(){try{var p=PresetCode.Import(shareCode.Text.Trim());string b=p.Name;int n=2;while(styles.Items.Exists(x=>string.Equals(x.Name,p.Name,StringComparison.OrdinalIgnoreCase)))p.Name=b+" ("+n+++" )";styles.Items.Add(p);styles.Save();ReloadPresets(p);RegisterHotkeys();}catch(Exception ex){MessageBox.Show(this,"导入失败："+ex.Message,"分享代码",MessageBoxButton.OK,MessageBoxImage.Warning);}}
  void AddRule(){var p=(gamePreset.SelectedItem as ComboBoxItem)?.Tag as StylePresetData;string n=processName.Text.Trim();if(p==null||n.Length==0)return;var r=settings.GameRules.Find(x=>string.Equals(x.ProcessName,n,StringComparison.OrdinalIgnoreCase));if(r==null){r=new GamePresetRule{ProcessName=n};settings.GameRules.Add(r);}r.PresetName=p.Name;settings.Save();RefreshRules();}void DeleteRule(){if(rules.SelectedItem is not GamePresetRule r)return;settings.GameRules.Remove(r);settings.Save();RefreshRules();}void RefreshRules(){rules.ItemsSource=null;rules.ItemsSource=settings.GameRules;}
  void CheckGame(){settings.GameAutoSwitchEnabled=AutoSwitch.IsChecked==true;settings.RestoreAfterGame=RestoreAfterGame.IsChecked==true;settings.FrameGenerationCompatibility=FrameProtection.IsChecked==true;settings.SyncAllDisplays=syncAll.IsChecked==true;if(!sessionReady)return;IntPtr fg=MonitorApi.GetForegroundWindow();bool full=MonitorApi.IsFullscreenWindow(fg);if(settings.FrameGenerationCompatibility&&full&&!softwareSuppressed){softwareSuppressed=true;try{softwareSat.Restore();recovery.SetSoftwareColorMayBeActive(false);}catch{}}if(!full&&softwareSuppressed){softwareSuppressed=false;if(activeStyle!=null)_=ApplySat(activeStyle.Saturation);}if(!settings.GameAutoSwitchEnabled)return;string proc=ForegroundProcess(fg);var rule=settings.GameRules.FirstOrDefault(x=>string.Equals(IOPath.GetFileNameWithoutExtension(x.ProcessName),IOPath.GetFileNameWithoutExtension(proc),StringComparison.OrdinalIgnoreCase));if(rule!=null&&activeGame==null){beforeGame=Capture("进入游戏前");activeGame=proc;var p=styles.Items.Find(x=>string.Equals(x.Name,rule.PresetName,StringComparison.OrdinalIgnoreCase));if(p!=null)ApplyPreset(p.DeepClone());}else if(rule==null&&activeGame!=null){activeGame=null;if(settings.RestoreAfterGame&&beforeGame!=null)ApplyPreset(beforeGame.DeepClone());}}
  static string ForegroundProcess(IntPtr h){try{GetWindowThreadProcessId(h,out uint id);return Process.GetProcessById((int)id).ProcessName+".exe";}catch{return"";}}
  string Diagnose(){var d=Display;var l=new List<string>{"系统："+Environment.OSVersion,"WPF retained-mode：已启用","软件颜色矩阵："+(softwareSat.IsAvailable?"可用":"不可用"),"游戏性能保护："+(settings.FrameGenerationCompatibility?"开启":"关闭"),"后台快捷键：已注册 "+registered.Count+" 项","Gamma 最近状态："+gamma.LastOperation};if(d!=null){l.Add("显示器："+d.Name);l.Add("DDC/CI 亮度："+(d.SupportsBrightness?"支持":"不支持"));l.Add("DDC/CI 对比度："+(d.SupportsContrast?"支持":"不支持"));l.Add("DDC/CI 饱和度："+(d.SupportsSaturation?"支持，但不自动恢复":"不支持"));l.Add("显示路径："+d.DisplayAdapterName+" / "+d.DisplayDeviceName);}foreach(var x in hotkeyStatus.Where(x=>x.Value.StartsWith("注册失败")))l.Add("快捷键冲突："+x.Key+" - "+x.Value);return string.Join(Environment.NewLine,l);}
  void UpdateCurve(){if(curve?.Parent is not Canvas c||c.ActualWidth<20)return;var pts=new PointCollection();double sh=Shadows.Value/200,hi=Highlights.Value/200,mid=Midtones.Value/100,ex=Exposure.Value/100;for(int i=0;i<=80;i++){double x=i/80d,y=x+sh*(1-x)*.45-hi*x*.38+mid*(.5-Math.Abs(x-.5))*.35+ex*.18;y=Math.Clamp(y,0,1);pts.Add(new Point(x*c.ActualWidth,(1-y)*c.ActualHeight));}curve.Points=pts;}
  void BuildTray(){string ip=IOPath.Combine(AppContext.BaseDirectory,"assets","shadepilot-icon.ico");if(File.Exists(ip))tray.Icon=new System.Drawing.Icon(ip);tray.Text="ShadePilot BETA 0.4.5";var m=new Forms.ContextMenuStrip();m.Items.Add("显示主界面",null,(_,__)=>Dispatcher.Invoke(()=>{Show();WindowState=WindowState.Normal;Activate();}));m.Items.Add("恢复软件画面",null,(_,__)=>Dispatcher.Invoke(ResetStyle));trayMonitorStatus=new Forms.ToolStripMenuItem("显示器：等待检测"){Enabled=false};trayHotkeyStatus=new Forms.ToolStripMenuItem("后台快捷键：等待注册"){Enabled=false};m.Items.Add(trayMonitorStatus);m.Items.Add(trayHotkeyStatus);m.Items.Add(new Forms.ToolStripSeparator());var auto=new Forms.ToolStripMenuItem("显示环境变化后自动重新应用"){Checked=settings.AutoReapply,CheckOnClick=true};auto.CheckedChanged+=(_,__)=>{settings.AutoReapply=auto.Checked;settings.Save();};m.Items.Add(auto);var close=new Forms.ToolStripMenuItem("关闭按钮退到后台"){Checked=settings.CloseToTray,CheckOnClick=true};close.CheckedChanged+=(_,__)=>{settings.CloseToTray=close.Checked;if(closeToTray!=null)closeToTray.IsChecked=close.Checked;settings.Save();};m.Items.Add(close);m.Items.Add(new Forms.ToolStripSeparator());m.Items.Add("退出",null,(_,__)=>Dispatcher.Invoke(()=>{exiting=true;Close();}));tray.ContextMenuStrip=m;tray.DoubleClick+=(_,__)=>Dispatcher.Invoke(()=>{Show();Activate();});tray.Visible=true;UpdateTrayStatus();}
