  void ClosingWindow(object s,System.ComponentModel.CancelEventArgs e){if(!exiting&&(closeToTray?.IsChecked??settings.CloseToTray)){e.Cancel=true;settings.CloseToTray=true;settings.Save();Hide();tray.ShowBalloonTip(1000,"ShadePilot","已转入后台，快捷键继续可用。",Forms.ToolTipIcon.Info);return;}exiting=true;gameTimer.Stop();hardwareTimer.Stop();recoveryTimer.Stop();SystemEvents.DisplaySettingsChanged-=DisplayEnvironmentChanged;SystemEvents.PowerModeChanged-=PowerModeChanged;SystemEvents.SessionEnding-=SessionEnding;Application.Current.Exit-=ApplicationExit;UnregisterHotkeys();crosshair?.Dispose();RestoreAndMarkClean("Normal exit");settings.StartWithWindows=startWindows?.IsChecked==true;settings.StartMinimized=startMinimized?.IsChecked==true;settings.CloseToTray=closeToTray?.IsChecked==true;settings.AutoReapply=autoReapply?.IsChecked==true;settings.GameAutoSwitchEnabled=AutoSwitch.IsChecked==true;settings.RestoreAfterGame=RestoreAfterGame.IsChecked==true;settings.FrameGenerationCompatibility=FrameProtection.IsChecked==true;settings.SyncAllDisplays=syncAll.IsChecked==true;settings.Save();foreach(var d in displays)d.Dispose();tray.Visible=false;tray.Dispose();softwareSat.Dispose();source?.RemoveHook(Hook);}
